// Browser-safe encoding only. Credentials are generated by the authenticated
// server and the mock machine consumes them through the same API as manual entry.
const prefix = 'strideeco:water:v1:';
const identifier = /^[\w-]{8,100}$/;

export function normalizeVoucherCode(value: unknown): string | null {
  if (typeof value !== 'string' || value.length > 80 || !/^[\da-f\s-]+$/i.test(value)) return null;
  const token = value.replace(/[\s-]/g, '').toUpperCase();
  return /^[\dA-F]{32}$/.test(token) ? token : null;
}

export function formatVoucherCode(value: string): string {
  const token = normalizeVoucherCode(value);
  return token ? token.match(/.{4}/g)!.join('-') : value;
}

export function voucherQrPayload(voucher: { id: string; token: string }): string {
  const token = normalizeVoucherCode(voucher.token);
  if (!identifier.test(voucher.id) || !token) throw new Error('Invalid water voucher.');
  return `${prefix}${voucher.id}:${token}`;
}

export function parseVoucherPayload(value: unknown): { id: string; token: string } | null {
  if (typeof value !== 'string' || value.length > 160 || !value.startsWith(prefix)) return null;
  const parts = value.slice(prefix.length).split(':');
  if (parts.length !== 2 || !identifier.test(parts[0]) || !/^[\dA-F]{32}$/.test(parts[1])) return null;
  return { id: parts[0], token: parts[1] };
}
